public function sortByDesc($callback, $options = SORT_REGULAR)
{
    if (is_array($callback) && ! is_callable($callback)) {
        foreach ($callback as $index => $key) {
            $comparison = Arr::wrap($key);

            $comparison[1] = SortDirection::Descending;

