    $command = array_merge($this->findComposer(), ['-V', '--no-ansi']);

    $process = $this->getProcess($command);

    $process->run();

    $output = $process->getOutput();

    if (preg_match('/(\d+(\.\d+){2})/', $output, $version)) {
        return $version[1];
    }

    return explode(' ', $output)[2] ?? null;
}
