public function flatten($depth = INF)
{
    $instance = new static(function () use ($depth) {
        foreach ($this as $item) {
            if (! is_array($item) && ! $item instanceof Enumerable) {
                yield $item;
            } elseif ($depth === 1) {
                yield from $item;
            } else {
                yield from (new static($item))->flatten($depth - 1);
            }
        }
    });

    return $instance->values();
}
