protected function compileForelse($expression)
{
    $empty = '$__empty_'.++$this->forElseCounter;

    preg_match('/\( *(.+) +as +(.+)\)$/is', $expression ?? '', $matches);

    if ($matches === []) {
        throw new ViewCompilationException('Malformed @forelse statement.');
