public function first(?callable $callback = null, $default = null)
{
    $iterator = $this->getIterator();

    if (is_null($callback)) {
        if (! $iterator->valid()) {
            return value($default);
        }

        return $iterator->current();
    }

    foreach ($iterator as $key => $value) {
        if ($callback($value, $key)) {
            return $value;
        }
    }

    return value($default);
}
