public static function start($value, $prefix)
{
    if ($prefix === '') {
        return $value;
    }

    if (! str_starts_with($value, $prefix)) {
        return $prefix.$value;
    }

    if (! str_starts_with($value, $prefix.$prefix)) {
        return $value;
    }

    $quoted = preg_quote($prefix, '/');

    return $prefix.preg_replace('/^(?:'.$quoted.')+/u', '', $value);
}
