    $expire = substr($contents, 0, 10);

    $currentOwner = $this->unserialize(substr($contents, 10));

    if ($currentOwner !== $expectedOwner || $this->currentTime() >= $expire) {
        $file->close();

        return false;
    }

    $file->truncate()
