    if (isset($this->customValues[$attribute][$value])) {
        return $this->customValues[$attribute][$value];
    }

    if (is_array($value)) {
        return 'array';
    }

    $key = "validation.values.{$attribute}.{$value}";

    if (($line = $this->translator->get($key)) !== $key) {
        return $line;
    }

    if (is_bool($value)) {
        return $value ? 'true' : 'false';
    }

    if (is_null($value)) {
        return 'empty';
    }

    return (string) $value;
}
