public function nth($step, $offset = 0)
{
    if ($step < 1) {
        throw new InvalidArgumentException('Step value must be at least 1.');
    }

    return new static(function () use ($step, $offset) {
        $position = 0;

        foreach ($this->slice($offset) as $item) {
            if ($position % $step === 0) {
                yield $item;
            }

            $position++;
        }
    });
}
